        [TestMethod]
        public async Task Velocity_BigKernelFrame_LaunchFromSmallStackThread_MatchesOracle() => await RunEmulatedTest(async accelerator =>
        {
            const int count = 64;
            var input = new int[count];
            for (int i = 0; i < count; i++) input[i] = i * 31 - 500;
            using var dIn = accelerator.Allocate1D(input);
            using var dOut = accelerator.Allocate1D<int>(count);
            var kernel = accelerator.LoadAutoGroupedStreamKernel<Index1D, ArrayView<int>, ArrayView<int>>(BigFrame_Kernel);
            if (accelerator.AcceleratorType is AcceleratorType.Velocity or AcceleratorType.CPU)
            {
                Exception? failure = null;
                var thread = new System.Threading.Thread(() =>
                {
                    try { kernel((Index1D)count, dIn.View, dOut.View); accelerator.Synchronize(); }
                    catch (Exception ex) { failure = ex; }
                }, 256 * 1024);
                thread.Start();
                thread.Join();
                if (failure != null) throw failure;
            }
            else
            {
                kernel((Index1D)count, dIn.View, dOut.View);
                await accelerator.SynchronizeAsync();
            }
            var got = await dOut.CopyToHostAsync<int>();
            for (int i = 0; i < count; i++)
                if (got[i] != BigFrame_Chain(input[i])) throw new Exception($"output[{i}] = {got[i]}, expected {BigFrame_Chain(input[i])}");
        });
    }
